import{U as e,W as t,nt as n,t as r}from"./chunks/framework.BPwQCpO3.js";var i=JSON.parse(`{"title":"ADR-0007: Why SQLite","description":"","frontmatter":{},"headers":[],"relativePath":"adr/ADR-0007-why-sqlite.md","filePath":"adr/ADR-0007-why-sqlite.md","lastUpdated":1793381793000}`),a={name:`adr/ADR-0007-why-sqlite.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="adr-0007-why-sqlite" tabindex="-1">ADR-0007: Why SQLite <a class="header-anchor" href="#adr-0007-why-sqlite" aria-label="Permalink to “ADR-0007: Why SQLite”">​</a></h1><ul><li>Status: Accepted</li><li>Date: 2026-10-31</li><li>Related: docs/guide/persistence.md §7</li></ul><h2 id="background" tabindex="-1">Background <a class="header-anchor" href="#background" aria-label="Permalink to “Background”">​</a></h2><p>Custos is a local-first engine: it must keep working when the network is down (events enqueued, state persisted), and it must recover unfinished recovery tasks after a crash; the user should not be required to install a database service first.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><p>SQLite (WAL mode, <code>libsqlite3-sys</code> bundled so all platforms build from source): single file, zero operations, transactions satisfy the crash-consistency write ordering; custos-store provides versioned migrations (<code>schema_migrations</code>, migrations only append) and a sync facade (the engine keeps a synchronous model).</p><h2 id="alternatives" tabindex="-1">Alternatives <a class="header-anchor" href="#alternatives" aria-label="Permalink to “Alternatives”">​</a></h2><ul><li><strong>PostgreSQL/MySQL</strong>: requires an external service — violates local-first; offline = amnesia.</li><li><strong>JSON files</strong>: no transactions, facts lost in the crash window; no indexes, audit queries degrade.</li><li><strong>Embedded KV (sled/redb)</strong>: insufficient maturity and query capability; audit retrieval would need custom building.</li></ul><h2 id="pros-and-cons" tabindex="-1">Pros and Cons <a class="header-anchor" href="#pros-and-cons" aria-label="Permalink to “Pros and Cons”">​</a></h2><p>Pros: deployment is a file; transactions give &quot;persist attempt before execution&quot; (ADR-0008) atomicity; SQL audit and the CLI&#39;s status/runs/incidents/notify queries reach directly. Cons: single writer (WAL + one connection suffices: one engine process); large tables need retention purging (§7.4 implemented).</p><h2 id="follow-up-impact" tabindex="-1">Follow-up Impact <a class="header-anchor" href="#follow-up-impact" aria-label="Permalink to “Follow-up Impact”">​</a></h2><ul><li>All persistence goes through custos-store; migrations V1→V3 exist, schema changes must use a new version number.</li><li>The notification queue (five states) and recovery state share the same SQLite file — offline drain works naturally.</li></ul>`,12)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};